var LS_LANG = "padbridge-docs-lang";
var LANG = "en";
try { var s = localStorage.getItem(LS_LANG); if (DOCS_I18N[s]) LANG = s; } catch (e) {}

function langInfo(code) {
  for (var i = 0; i < LANGS.length; i++) if (LANGS[i].code === code) return LANGS[i];
  return LANGS[0];
}
function t(key) {
  var d = DOCS_I18N[LANG] || DOCS_I18N.en;
  return (d && d[key] != null) ? d[key] : ((DOCS_I18N.en && DOCS_I18N.en[key]) || key);
}
function applyLang(code, save) {
  if (!DOCS_I18N[code]) code = "en";
  LANG = code;
  var info = langInfo(code);
  document.documentElement.lang = code;
  if (info.rtl) document.documentElement.setAttribute("dir", "rtl");
  else document.documentElement.removeAttribute("dir");
  var nodes = document.querySelectorAll("[data-i18n]");
  for (var i = 0; i < nodes.length; i++) {
    var k = nodes[i].getAttribute("data-i18n");
    if (k) nodes[i].textContent = t(k);
  }
  var title = document.querySelector("title");
  if (title) title.textContent = t("title");
  var md = document.querySelector('meta[name="description"]');
  if (md) md.setAttribute("content", t("desc"));
  var flag = document.getElementById("langflag");
  if (flag) flag.innerHTML = FLAGS[info.flag] || "";
  var list = document.getElementById("langlist");
  if (list) {
    var html = "";
    for (var j = 0; j < LANGS.length; j++) {
      var L = LANGS[j];
      html += '<button type="button" class="langopt" role="menuitem" data-lang="' + L.code + '" data-state="' + (L.code === LANG ? "on" : "off") + '"' + (L.rtl ? ' dir="rtl"' : "") + '><span class="flag">' + (FLAGS[L.flag] || "") + "</span><span>" + L.name + "</span></button>";
    }
    list.innerHTML = html;
  }
  var sw = document.querySelectorAll("[data-he]");
  for (var m = 0; m < sw.length; m++) {
    var el = sw[m], at = el.tagName === "A" ? "href" : "src";
    if (!el.getAttribute("data-en")) el.setAttribute("data-en", el.getAttribute(at));
    el.setAttribute(at, code === "he" ? el.getAttribute("data-he") : el.getAttribute("data-en"));
  }
  if (save) try { localStorage.setItem(LS_LANG, code); } catch (e) {}
}
function initLangUI() {
  var btn = document.getElementById("langbtn");
  var list = document.getElementById("langlist");
  if (!btn || !list) return;
  btn.addEventListener("click", function (e) {
    e.stopPropagation();
    list.classList.toggle("show");
  });
  list.addEventListener("click", function (e) {
    var b = e.target.closest("[data-lang]");
    if (!b) return;
    applyLang(b.getAttribute("data-lang"), true);
    list.classList.remove("show");
  });
  document.addEventListener("click", function () { list.classList.remove("show"); });
  applyLang(LANG, false);
}
document.addEventListener("DOMContentLoaded", initLangUI);
